'use client'

import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import type { User } from '@supabase/supabase-js'

type OnlineUser = {
  id: string
  nickname: string
}

export default function Feed({ user }: { user: User }) {
  const [onlineUsers, setOnlineUsers] = useState<OnlineUser[]>([])
  const displayName =
    user.user_metadata?.nickname || user.email?.split('@')[0] || 'User'

  const supabase = createClient()

  // Online users (Presence)
  useEffect(() => {
    const channel = supabase.channel('online-users', {
      config: {
        presence: {
          key: user.id,
        },
      },
    })

    channel
      .on('presence', { event: 'sync' }, () => {
        const state = channel.presenceState()
        const users: OnlineUser[] = []

        Object.values(state).forEach((presences: any) => {
          presences.forEach((presence: any) => {
            users.push({
              id: presence.user_id,
              nickname: presence.nickname,
            })
          })
        })

        const uniqueUsers = Array.from(
          new Map(users.map((u) => [u.id, u])).values()
        )
        setOnlineUsers(uniqueUsers)
      })
      .subscribe(async (status) => {
        if (status === 'SUBSCRIBED') {
          await channel.track({
            user_id: user.id,
            nickname: displayName,
            online_at: new Date().toISOString(),
          })
        }
      })

    return () => {
      supabase.removeChannel(channel)
    }
  }, [user.id, displayName])

  return (
    <div className="flex flex-col h-full bg-[#2b2d31] text-gray-100">
      {/* Server / App Header */}
      <div className="px-4 py-3 border-b border-[#1e1f22] font-semibold text-sm tracking-wide">
        Chat Room
      </div>

      {/* Rooms Section */}
      <div className="px-2 pt-4">
        <p className="px-2 text-xs font-semibold text-gray-400 uppercase mb-1">
          Rooms
        </p>

        <button className="w-full flex items-center gap-2 px-2 py-1.5 rounded bg-[#404249] text-white text-sm">
          <span className="text-gray-400">#</span>
          general
        </button>

        {/* Future rooms will go here */}
        <button className="w-full flex items-center gap-2 px-2 py-1.5 rounded text-gray-400 hover:bg-[#35373c] hover:text-gray-200 text-sm mt-0.5">
          <span>#</span>
          random
        </button>
      </div>

      {/* Online Members */}
      <div className="mt-6 px-2 flex-1 overflow-y-auto">
        <p className="px-2 text-xs font-semibold text-gray-400 uppercase mb-2">
          Online — {onlineUsers.length}
        </p>

        <div className="space-y-1">
          {onlineUsers.map((onlineUser) => (
            <div
              key={onlineUser.id}
              className="flex items-center gap-2 px-2 py-1.5 rounded hover:bg-[#35373c] cursor-default"
            >
              <div className="relative">
                <div className="w-8 h-8 rounded-full bg-indigo-500 flex items-center justify-center text-sm font-medium text-white">
                  {onlineUser.nickname.charAt(0).toUpperCase()}
                </div>
                <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-[#2b2d31]" />
              </div>

              <span className="text-sm text-gray-200">
                {onlineUser.nickname}
                {onlineUser.id === user.id && (
                  <span className="text-gray-500 text-xs ml-1">(you)</span>
                )}
              </span>
            </div>
          ))}

          {onlineUsers.length === 0 && (
            <p className="px-2 text-sm text-gray-500">No one online</p>
          )}
        </div>
      </div>

      {/* User panel at bottom */}
      <div className="p-2 bg-[#232428] border-t border-[#1e1f22]">
        <div className="flex items-center gap-2 px-2 py-1.5 rounded hover:bg-[#35373c]">
          <div className="relative">
            <div className="w-8 h-8 rounded-full bg-indigo-500 flex items-center justify-center text-sm font-medium text-white">
              {displayName.charAt(0).toUpperCase()}
            </div>
            <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-[#232428]" />
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium truncate">{displayName}</p>
            <p className="text-xs text-gray-400">Online</p>
          </div>
        </div>
      </div>
    </div>
  )
}